	stateProvider       addrs.AbsProviderConfig
	stateConfig         *configs.Resource

	importToExpr     hcl.Expression
	importIDExpr     hcl.Expression
	importKeyData    instances.RepetitionData
	importTargetAddr addrs.AbsResourceInstance
	importPartial    addrs.PartialExpandedResource
	importIndexExpr  hcl.Expression
	importIndex      hcl.TraverseIndex
	importTraversal  hcl.Traversal
