	selfRefAddr   addrs.Resource
	selfRefExpr   hcl.Expression
	selfRefBody   hcl.Body
	selfRefSchema providers.ProviderSchema
	selfRefDiag   func(ref *addrs.Reference) *hcl.Diagnostic
	selfRefList   []string
	selfRefFilter []*addrs.Reference

	referenceConfig       *configs.Resource
	collectedRefs         []*addrs.Reference
